#include <bits/stdc++.h>

#define endl '\n'

using namespace std;

typedef pair<int, int> ipair;

const int MAXSZ = 200200;
const int INF = 2e9;

inline int add(int a, int b) {
	return (a + b >= 9 ? a + b - 9 : a + b);
}

inline int sub(int a, int b) {
	return (a < b ? a + 9 - b : a - b);
}

inline int mul(int a, int b) {
	return a * b % 9;
}

int sz, n, m;
string s;
int ps[MAXSZ];
vector<int> D[9];

void build() {
	sz = s.size();
	for (int md = 0; md < 9; ++md)
		D[md].clear();
	for (int i = 0; i < sz; ++i)
		ps[i + 1] = ps[i] + (s[i] - '0');
	for (int i = 0; i + n <= sz; ++i)
		D[(ps[i + n] - ps[i]) % 9].push_back(i);
}

ipair solve(int l, int r, int k) {
	int x = (ps[r] - ps[l]) % 9;
	ipair ans {INF, INF};
	for (int a = 0; a < 9; ++a) {
		int b = sub(k, mul(a, x));
		if (D[a].empty() || D[b].empty()) continue;
		if (a != b)
			ans = min(ans, make_pair(D[a].front(), D[b].front()));
		else if (D[a].size() >= 2)
			ans = min(ans, make_pair(D[a].front(), D[a][1]));
	}
	if (ans == make_pair(INF, INF))
		return {-2, -2};
	return ans;
}

int main() {
	ios_base::sync_with_stdio(false), cin.tie(NULL), cout.tie(NULL);
	int t; cin >> t;
	while (t--) {
		cin >> s >> n >> m;
		build();
		for (int i = 0; i < m; ++i) {
			int l, r, k; cin >> l >> r >> k, --l;
			auto [ans1, ans2] = solve(l, r, k);
			cout << ++ans1 << ' ' << ++ans2 << endl;
		}
	}
}

#include<cstdio>
#include<cstring>
const int N=505;
const int Mod=1e9+7;
char s[N],t[N];
int n,m;
int f[N],g[N];
int p[N],tot;
inline void Init(){
	scanf("%s",s+1);
	scanf("%s",t+1);
	n=strlen(s+1);
	m=strlen(t+1);
	tot=0;
	for(int i=1;i+m-1<=n;i++){
		bool flg=1;
		for(int j=1;j<=m;j++)
			if(s[i+j-1]!=t[j]) flg=0;
		if(flg) p[++tot]=i;
	}
	return ;
}
inline int addv(int x,int y){
	int s=x+y;
	if(s>=Mod) s-=Mod;
	return s;
}
inline int subv(int x,int y){
	int s=x-y;
	if(s<0) s+=Mod;
	return s;
}
inline void add(int&x,int y){
	x=addv(x,y);
	return ;
}
inline void sub(int&x,int y){
	x=subv(x,y);
	return ;
}
inline void Solve(){
	memset(f,0x3f,sizeof(f));
	memset(g,0,sizeof(g));
	p[0]=-N;
	f[0]=0;
	g[0]=1;
	p[++tot]=n+m;
	for(int i=0;i<tot;i++){
		int j=i+1;
		while(j<=tot&&p[j]<=p[i]+m-1) j++;
		for(int k=j;p[j]+m-1>=p[k]&&k<=tot;k++){
			if(f[i]+1<f[k]){
				f[k]=f[i]+1;
				g[k]=g[i];
			}
			else if(f[i]+1==f[k]) add(g[k],g[i]);
		}
	}
	printf("%d %d\n",f[tot]-1,g[tot]);
	return ;
}
int T;
int main(){
	for(scanf("%d",&T);T;T--){
		Init();
		Solve();
	}
	return 0;
}
